create or replace function public.inventory_logistics_can_manage() returns boolean language sql stable security invoker set search_path=public,pg_temp as $fn$ select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=(select auth.uid()) and p.school_id=public.my_school_id() and p.active=true and (r.name in ('promoteur','administrateur','logisticien') or coalesce((p.permission_overrides->>'inventory')::boolean,false) or coalesce((p.permission_overrides->>'inventory_logistics')::boolean,false))) $fn$;
do $pol$ declare t text; begin foreach t in array array['inventory_locations','inventory_assets','inventory_suppliers','inventory_requests','inventory_request_lines','inventory_purchase_orders','inventory_purchase_lines','inventory_maintenance','inventory_audits','inventory_audit_lines','inventory_transfers'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists %I on public.%I',t||'_school_read',t); execute format('create policy %I on public.%I for select to authenticated using (school_id=public.my_school_id())',t||'_school_read',t); execute format('drop policy if exists %I on public.%I',t||'_manage_insert',t); execute format('create policy %I on public.%I for insert to authenticated with check (school_id=public.my_school_id() and public.inventory_logistics_can_manage())',t||'_manage_insert',t); execute format('drop policy if exists %I on public.%I',t||'_manage_update',t); execute format('create policy %I on public.%I for update to authenticated using (school_id=public.my_school_id() and public.inventory_logistics_can_manage()) with check (school_id=public.my_school_id() and public.inventory_logistics_can_manage())',t||'_manage_update',t); execute format('drop policy if exists %I on public.%I',t||'_manage_delete',t); execute format('create policy %I on public.%I for delete to authenticated using (school_id=public.my_school_id() and public.inventory_logistics_can_manage())',t||'_manage_delete',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $pol$;
insert into public.module_catalog(module_key,name,description,category,implementation_status,default_enabled) values ('inventory','Stocks et logistique','Stocks, immobilisations, demandes, achats, maintenance, inventaires et transferts','Administration','available',true) on conflict(module_key) do update set name=excluded.name,description=excluded.description,category=excluded.category,implementation_status='available',updated_at=now();
insert into public.school_modules(school_id,module_key,enabled) select id,'inventory',true from public.schools on conflict(school_id,module_key) do update set enabled=true,updated_at=now();